const schools=[...baseSchools,...Array.from({length:16},(_,i)=>({id:`school-${String(i+5).padStart(2,'0')}`,name:generatedSchoolNames[i],city:`${generatedCities[i]}, ${generatedStates[i]}`,students:4867+i*100,teachers:340+i*15,staff:760+i*15,admin:String(2+(i%5)),plan:['Starter','Professional','Enterprise','Free'][i%4],status:i%7===0?'Trial':'Active',revenue:`\u20B9${(5.4+i*0.7).toFixed(1)} L`,activity:`${i+3} min ago`}))];function readSchoolRows(){try{const value=localStorage.getItem('schoolos_superadmin_schools');if(!value)return schools;const saved=JSON.parse(value) as typeof schools;const merged=new Map(schools.map(row=>[row.id,row]));saved.forEach(row=>merged.set(row.id,row));return [...merged.values()];}catch{return schools;}}

